<?php
declare(strict_types=1);$direction=($_GET['richtung']??'de-it')==='it-de'?'it-de':'de-it';$type=($_GET['typ']??'wort')==='satz'?'satz':'wort';$lr=(string)($_GET['lektion']??'');$lesson=$lr!==''&&ctype_digit($lr)?(int)$lr:null;$search=trim((string)($_GET['suche']??''));$cards=$cardRepository->learningCards($direction,$type,$lesson,$search);?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Italienische Lernkarten – Druck</title><link rel="stylesheet" href="assets/css/print.css"></head><body><div class="toolbar"><form method="get" action="index.php"><input type="hidden" name="action" value="pdf"><input type="hidden" name="richtung" value="<?=Html::e($direction)?>"><input type="hidden" name="typ" value="<?=Html::e($type)?>"><?php if($lesson!==null):?><input type="hidden" name="lektion" value="<?=$lesson?>"><?php endif;?><input type="search" name="suche" value="<?=Html::e($search)?>" placeholder="Wort oder Satz suchen"><button>Suchen</button></form><div><button onclick="window.print()">Drucken / Als PDF speichern</button> <a class="button" href="index.php?richtung=<?=$direction?>&typ=<?=$type?><?= $lesson!==null?'&lektion='.$lesson:''?>">Zurück</a></div></div><main class="document"><h1>Italienische Lernkarten</h1><p class="subtitle"><?=$direction==='de-it'?'Deutsch → Italienisch':'Italienisch → Deutsch'?> · <?=$type==='wort'?'Wörter':'Sätze'?><?=$lesson!==null?' · Lektion '.$lesson:''?></p><?php foreach($cards as $card):?><section class="print-card"><div class="number">DB-ID #<?=(int)$card['id']?> · Lektion <?=Html::e((string)($card['lektion']??'–'))?></div><div class="question"><?=Html::e($card['frage'])?></div><div class="answer"><?=nl2br(Html::e($card['antwort']))?></div><?php if($type==='wort'&&trim((string)$card['satz_it'])!==''):?><div class="examples"><div><?=Html::e($card['satz_it'])?></div><div><?=Html::e($card['satz_de'])?></div></div><?php endif;?></section><?php endforeach;?></main></body></html>
